from pysat.solvers import Glucose3
from pysat.card import CardEnc
import itertools

n = 21
solver = Glucose3()

# Variables for edges
def var(i, j):
    if i > j:
        i, j = j, i
    # i < j
    # index from 1
    # i from 0 to n-2, j from i+1 to n-1
    # offset = sum_{k=0}^{i-1} (n - 1 - k)
    offset = i * n - i * (i + 1) // 2 - i
    return offset + (j - i)

# No 3-cycles
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-var(c[0], c[1]), -var(c[1], c[2]), -var(c[0], c[2])])

# No 4-cycles
for c in itertools.combinations(range(n), 4):
    for p in itertools.permutations(c):
        # To avoid duplicates, fix the first element to be the smallest, and the second < fourth
        if p[0] == min(p) and p[1] < p[3]:
            solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[0])])

# No 5-cycles
for c in itertools.combinations(range(n), 5):
    for p in itertools.permutations(c):
        if p[0] == min(p) and p[1] < p[4]:
            solver.add_clause([-var(p[0], p[1]), -var(p[1], p[2]), -var(p[2], p[3]), -var(p[3], p[4]), -var(p[4], p[0])])

# Degree constraints
vpool = n * (n - 1) // 2 + 1
for i in range(n):
    edges = [var(i, j) for j in range(n) if i != j]
    # degree >= 3
    cnf_ge = CardEnc.atleast(lits=edges, bound=3, vpool=vpool)
    for clause in cnf_ge.clauses:
        solver.add_clause(clause)
    vpool = max([abs(l) for clause in cnf_ge.clauses for l in clause] + [vpool]) + 1

    # degree <= 5
    cnf_le = CardEnc.atmost(lits=edges, bound=5, vpool=vpool)
    for clause in cnf_le.clauses:
        solver.add_clause(clause)
    vpool = max([abs(l) for clause in cnf_le.clauses for l in clause] + [vpool]) + 1

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if model[var(i, j) - 1] > 0:
                edges.append((i, j))
    print(edges)
else:
    print("UNSAT")

