import itertools

n = 21
solver = Glucose3()
vpool = IDPool()

# Variables for edges
def var(i, j):
    if i > j:
        i, j = j, i
    return vpool.id(f"e_{i}_{j}")

# No 3-cycles
for c in itertools.combinations(range(n), 3):
    solver.add_clause([-var(c[0], c[1]), -var(c[1], c[2]), -var(c[0], c[2])])

