from collections import deque

edges = [(0, 7), (0, 9), (0, 10), (0, 18), (1, 6), (1, 12), (1, 18), (2, 4), (2, 11), (2, 13), (2, 19), (3, 5), (3, 7), (3, 8), (4, 10), (4, 16), (5, 12), (5, 16), (6, 13), (6, 14), (6, 15), (7, 13), (8, 14), (8, 17), (9, 11), (9, 15), (10, 14), (11, 12), (15, 20), (16, 20), (17, 19), (17, 20), (18, 19)]

adj = {i: [] for i in range(21)}
for u, v in edges:
    adj[u].append(v)
    adj[v].append(u)

def get_girth(adj):
    min_cycle = float('inf')
    for start in range(21):
        dist = {start: 0}
        parent = {start: -1}
        q = deque([start])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    min_cycle = min(min_cycle, dist[u] + dist[v] + 1)
    return min_cycle

print("Girth:", get_girth(adj))
print("Degrees:", [len(adj[i]) for i in range(21)])
